-- 04_grammar_points.sql: Grammar Points for Spanish Course
INSERT INTO grammar_points (
    id, course_id, unit_id, slug, cefr_level, ordinal, title, short_explanation, rule_text, common_trap, examples
)
VALUES
    ('b0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'ser-personal-pronouns', 'A1', 1, 'Subject pronouns and ser', 'Use ser for permanent identity and origin.', 'Yo soy, tú eres, él/ella/usted es, nosotros somos, ellos son. In Spanish, subject pronouns are usually omitted unless emphasizing.', 'Confusing ser with estar when talking about identity.', '["Yo soy estudiante.","¿De dónde eres?","Ella es de Madrid."]'::jsonb),
    ('b0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000002', 'yes-no-questions-question-words', 'A1', 2, 'Yes/no questions and question words', 'Ask simple questions with inverted pitch or interrogative words.', 'Question words always carry an accent: ¿qué?, ¿cómo?, ¿dónde?, ¿cuándo?, ¿por qué?, ¿cuánto?', 'Forgetting the accent mark on question words or confusing qué and cuál.', '["¿Cómo te llamas?","¿Hablas español?","¿Dónde vives?"]'::jsonb),
    ('b0000000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000003', 'present-regular-reflexive-intro', 'A1', 3, 'Present regular verbs and reflexive intro', 'Conjugate -ar, -er, -ir verbs for everyday actions.', '-ar: -o, -as, -a, -amos, -an. Reflexive verbs use me, te, se, nos, se.', 'Placing reflexive pronouns after conjugated verbs instead of before.', '["Me levanto a las siete.","Trabajo de lunes a viernes.","¿A qué hora desayunas?"]'::jsonb),
    ('b0000000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000004', 'querer-quisiera-articles', 'A1', 4, 'Querer, quisiera, and articles', 'Polite ordering formulas and noun-gender matching.', 'Use quisiera for polite requests. Nouns ending in -o are typically masculine (el/un), -a feminine (la/una).', 'Saying *yo quiero to a waiter instead of the softer quisiera or me gustaría.', '["Quisiera un café con leche, por favor.","Una mesa para dos.","¿Cuánto cuesta el menú?"]'::jsonb),
    ('b0000000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000005', 'estar-hay-prepositions', 'A1', 5, 'Estar for location, hay, and prepositions', 'Locating objects, places, and describing existence.', 'Use hay for existence (there is/are) with un/una/numbers. Use estar for specific location (el banco está...).', 'Using hay with definite articles (*hay el banco).', '["¿Hay una farmacia cerca?","El museo está al lado del parque.","Gira a la izquierda."]'::jsonb),
    ('b0000000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000007', 'preterite-regular-ir-ser', 'A2', 6, 'Preterite regular verbs, ir, and ser', 'Describing completed actions in the past.', '-ar: -é, -aste, -ó, -amos, -aron. -er/-ir: -í, -iste, -ió, -imos, -ieron. Ir and ser share fui, fuiste, fue, fuimos, fueron.', 'Mixing preterite endings between -ar and -er verbs.', '["Ayer salí con mis amigos.","Fui al cine el sábado.","Comí una paella riquísima."]'::jsonb),
    ('b0000000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000008', 'demonstratives-direct-objects', 'A2', 7, 'Demonstratives and direct objects', 'Referring to items and pointing them out.', 'este/esta/estos/estas (this/these), ese/esa/esos/esas (that/those). Direct object pronouns: lo, la, los, las.', 'Placing object pronoun after conjugated verb (*quiero lo).', '["¿Cuánto cuesta esta camisa?","La compro.","Prefiero ese sombrero."]'::jsonb),
    ('b0000000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000009', 'ir-a-infinitive-tener-que', 'A2', 8, 'Ir a + infinitive and tener que', 'Expressing near future plans and immediate obligation.', 'Ir a + infinitive expresses what you are going to do. Tener que + infinitive expresses necessity.', 'Forgetting the preposition a after ir (*voy comer).', '["Voy a viajar a México.","Tengo que trabajar mañana.","¿Qué vas a hacer este fin de semana?"]'::jsonb),
    ('b0000000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000013', 'preterite-vs-imperfect', 'B1', 9, 'Preterite vs imperfect narration', 'Contrasting completed events with ongoing backgrounds.', 'Preterite narrates plot points (what happened). Imperfect sets the scene (habitual actions, time, weather, states).', 'Using preterite for background descriptions (*estuvo lloviendo cuando salí).', '["Hacía sol cuando llegué a la playa.","Mientras estudiaba, sonó el teléfono.","De niño jugaba al fútbol todos los días."]'::jsonb),
    ('b0000000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000019', 'subjunctive-triggers-intro', 'B2', 10, 'Subjunctive mood triggers', 'Expressing doubt, desire, emotion, and uncertainty.', 'Triggered by expressions of will/emotion + que + change of subject: quiero que, espero que, dudo que.', 'Using indicative after expressions of doubt (*dudo que viene).', '["Espero que tengas un buen viaje.","Dudo que sea verdad.","Quiero que me ayudes con esto."]'::jsonb)
ON CONFLICT (course_id, slug) DO UPDATE SET
    cefr_level = EXCLUDED.cefr_level,
    ordinal = EXCLUDED.ordinal,
    title = EXCLUDED.title,
    short_explanation = EXCLUDED.short_explanation,
    rule_text = EXCLUDED.rule_text,
    common_trap = EXCLUDED.common_trap,
    examples = EXCLUDED.examples;
